import java.util.*;

class Solution {
    public int maxRepOpt1(String text) {
        int[] counts = new int[26];
        for (char c : text.toCharArray()) counts[c - 'a']++;

        List<int[]> groups = new ArrayList<>();
        int i = 0, n = text.length();
        while (i < n) {
            int j = i;
            while (j < n && text.charAt(j) == text.charAt(i)) j++;
            groups.add(new int[]{text.charAt(i) - 'a', j - i});
            i = j;
        }

        int res = 0;
        int m = groups.size();
        for (int k = 0; k < m; k++) {
            int ch = groups.get(k)[0];
            int len = groups.get(k)[1];
            int total = counts[ch];
            res = Math.max(res, Math.min(len + 1, total));
            if (k + 2 < m && groups.get(k + 2)[0] == ch && groups.get(k + 1)[1] == 1) {
                int combined = len + groups.get(k + 2)[1];
                res = Math.max(res, Math.min(combined + 1, total));
            }
        }
        return res;
    }
}

